from pathlib import Path

root = Path(".")
ledger_path = root / "szl_energy_ledger.py"
tests_path = root / "test_energy_ledger.py"

ledger = ledger_path.read_text(encoding="utf-8")

constants_anchor = 'DEFAULT_PRICE_PER_KWH_CENTS = int(os.getenv("STRIPE_PRICE_PER_KWH_CENTS", "45"))\n'
constants_replacement = 'DEFAULT_PRICE_PER_KWH_CENTS = int(os.getenv("STRIPE_PRICE_PER_KWH_CENTS", "45"))\n\n# The public ledger endpoint is an operational projection, not an unbounded dump.\n# The full chain remains in the durable store and is verified/tallied in full, while\n# the GET response carries a bounded recent window so proxies and clients always\n# receive complete valid JSON. The investor smoke reader caps bodies at 512 KiB.\nDEFAULT_LEDGER_PAGE_LIMIT = 50\nMAX_LEDGER_PAGE_LIMIT = 200\nMAX_LEDGER_RECEIPTS_BYTES = 384_000\n'
if constants_anchor not in ledger:
    raise SystemExit("energy constants anchor not found")
ledger = ledger.replace(constants_anchor, constants_replacement, 1)

summary_anchor = '    def summary(self) -> dict:\n        """Full ledger view for the GET /energy/ledger endpoint."""\n        return {\n            "ok": True,\n            "receipts": self.entries(),\n            "chain": self.verify(),\n            "totals": self.totals(),\n            "persistence": self.persistence_info(),\n            "storage": self.storage_health(),\n            "price_per_kwh_cents": self.price_per_kwh_cents,\n            "stripe_mode": "live" if os.getenv("STRIPE_API_KEY") else "dry-run",\n            "doctrine": DOCTRINE_NOTE,\n            "timestamp_utc": datetime.now(timezone.utc).isoformat(),\n        }\n'
summary_replacement = '    def summary(\n        self,\n        limit: int = DEFAULT_LEDGER_PAGE_LIMIT,\n        offset_from_latest: int = 0,\n    ) -> dict:\n        """Bounded public view of the complete durable energy ledger.\n\n        Chain verification and totals always cover the full in-memory chain. Only the\n        returned ``receipts`` collection is windowed, newest window by default and\n        chronological inside that window. This prevents a valid but growing ledger\n        from being truncated mid-JSON by an edge/client body cap.\n\n        ``offset_from_latest`` is the number of newest entries to skip. Callers can\n        walk older windows without changing or minting any receipt.\n        """\n        try:\n            requested_limit = int(limit)\n        except (TypeError, ValueError):\n            requested_limit = DEFAULT_LEDGER_PAGE_LIMIT\n        limit = max(1, min(MAX_LEDGER_PAGE_LIMIT, requested_limit))\n        try:\n            offset = max(0, int(offset_from_latest))\n        except (TypeError, ValueError):\n            offset = 0\n\n        total = len(self._entries)\n        end = max(0, total - offset)\n        start = max(0, end - limit)\n        receipts = list(self._entries[start:end])\n\n        # A receipt may carry an unexpectedly large but valid metadata field. Enforce\n        # a byte budget as well as an item limit, dropping only the oldest item in the\n        # current window until the transport projection is safely bounded.\n        transport_truncated = False\n        while receipts:\n            encoded = json.dumps(\n                receipts, sort_keys=True, separators=(",", ":"), ensure_ascii=False\n            ).encode("utf-8")\n            if len(encoded) <= MAX_LEDGER_RECEIPTS_BYTES:\n                break\n            receipts.pop(0)\n            start += 1\n            transport_truncated = True\n\n        returned = len(receipts)\n        first_seq = receipts[0].get("seq") if receipts else None\n        last_seq = receipts[-1].get("seq") if receipts else None\n        has_older = start > 0\n        has_newer = end < total\n\n        return {\n            "ok": True,\n            "receipts": receipts,\n            "page": {\n                "order": "ascending-within-window",\n                "window": "latest",\n                "requested_limit": requested_limit,\n                "limit": limit,\n                "max_limit": MAX_LEDGER_PAGE_LIMIT,\n                "offset_from_latest": offset,\n                "returned": returned,\n                "total": total,\n                "first_seq": first_seq,\n                "last_seq": last_seq,\n                "has_older": has_older,\n                "has_newer": has_newer,\n                "next_offset_from_latest": (\n                    offset + returned if has_older else None\n                ),\n                "previous_offset_from_latest": (\n                    max(0, offset - limit) if has_newer else None\n                ),\n                "transport_truncated": transport_truncated,\n                "receipt_byte_budget": MAX_LEDGER_RECEIPTS_BYTES,\n                "full_chain_in_response": returned == total,\n            },\n            "chain": self.verify(),\n            "totals": self.totals(),\n            "persistence": self.persistence_info(),\n            "storage": self.storage_health(),\n            "price_per_kwh_cents": self.price_per_kwh_cents,\n            "stripe_mode": "live" if os.getenv("STRIPE_API_KEY") else "dry-run",\n            "doctrine": DOCTRINE_NOTE,\n            "timestamp_utc": datetime.now(timezone.utc).isoformat(),\n        }\n'
if summary_anchor not in ledger:
    raise SystemExit("energy summary anchor not found")
ledger = ledger.replace(summary_anchor, summary_replacement, 1)

handler_anchor = '    def _h_ledger(request: _Request):\n        return JSONResponse(handle_ledger())\n'
handler_replacement = '    def _h_ledger(request: _Request):\n        # Query values are transport controls only. This remains a read-only route:\n        # it never appends, signs, bills, or mints a receipt.\n        try:\n            limit = int(request.query_params.get("limit", DEFAULT_LEDGER_PAGE_LIMIT))\n        except (TypeError, ValueError):\n            limit = DEFAULT_LEDGER_PAGE_LIMIT\n        try:\n            offset = int(request.query_params.get("offset_from_latest", 0))\n        except (TypeError, ValueError):\n            offset = 0\n        response = JSONResponse(\n            get_ledger().summary(\n                limit=limit,\n                offset_from_latest=offset,\n            )\n        )\n        response.headers["Cache-Control"] = "no-store"\n        return response\n'
if handler_anchor not in ledger:
    raise SystemExit("energy route handler anchor not found")
ledger = ledger.replace(handler_anchor, handler_replacement, 1)
ledger_path.write_text(ledger, encoding="utf-8", newline="\n")

tests = tests_path.read_text(encoding="utf-8")
if "import json\n" not in tests:
    tests = tests.replace("import os\n", "import json\nimport os\n", 1)

test_anchor = '# ---------------------------------------------------------------------------\n# Persistence across redeploy — the demo risk this guard exists for. The receipt\n'
test_insert = 'def test_ledger_summary_defaults_to_bounded_latest_window():\n    led, tmp = _ledger()\n    try:\n        for index in range(60):\n            led.append_job(\n                _fresh_measured_job(\n                    joules=10_000.0 + index,\n                    model=f"bounded-{index}",\n                ),\n                now=NOW,\n            )\n        summary = led.summary()\n        seqs = [entry["seq"] for entry in summary["receipts"]]\n        assert seqs == list(range(10, 60))\n        assert summary["page"]["returned"] == 50\n        assert summary["page"]["total"] == 60\n        assert summary["page"]["has_older"] is True\n        assert summary["chain"]["length"] == 60\n        assert summary["totals"]["jobs"] == 60\n    finally:\n        _cleanup(tmp)\n\n\ndef test_ledger_summary_paginates_from_latest_without_mutation():\n    led, tmp = _ledger()\n    try:\n        for index in range(12):\n            led.append_job(\n                _fresh_measured_job(\n                    joules=20_000.0 + index,\n                    model=f"page-{index}",\n                ),\n                now=NOW,\n            )\n        before = led.verify()["length"]\n        page = led.summary(limit=4, offset_from_latest=4)\n        assert [entry["seq"] for entry in page["receipts"]] == [4, 5, 6, 7]\n        assert page["page"]["has_older"] is True\n        assert page["page"]["has_newer"] is True\n        assert led.verify()["length"] == before\n    finally:\n        _cleanup(tmp)\n\n\ndef test_ledger_summary_enforces_transport_byte_budget():\n    led, tmp = _ledger()\n    try:\n        for index in range(60):\n            led.append_job(\n                _fresh_measured_job(\n                    joules=30_000.0 + index,\n                    model=f"byte-budget-{index}",\n                ),\n                now=NOW,\n            )\n        for entry in led._entries:\n            entry["transport_test_pad"] = "x" * 12_000\n        summary = led.summary(limit=200)\n        encoded = json.dumps(\n            summary, sort_keys=True, separators=(",", ":")\n        ).encode("utf-8")\n        assert len(encoded) < 512_000\n        assert summary["page"]["transport_truncated"] is True\n        assert summary["page"]["returned"] < summary["page"]["total"]\n        assert summary["chain"]["length"] == 60\n    finally:\n        _cleanup(tmp)\n\n\n# ---------------------------------------------------------------------------\n# Persistence across redeploy — the demo risk this guard exists for. The receipt\n'
if test_anchor not in tests:
    raise SystemExit("energy test insertion anchor not found")
tests = tests.replace(test_anchor, test_insert, 1)
tests_path.write_text(tests, encoding="utf-8", newline="\n")
